// header.h
typedef void (*FrameCb)(const uint8_t* frame, size_t w, size_t h, void* user);
typedef struct Decoder Decoder;
Decoder* decoder_create(const uint8_t* init_data, size_t init_len, FrameCb cb, void* user);
void decoder_feed(Decoder* d, const uint8_t* data, size_t len);
void decoder_close(Decoder* d);
